struct LingCefAsyncState {
    std::mutex mutex;
    std::condition_variable changed;
    int status = 0; // 0等待、1运行、2成功、3失败、4取消
    int messageId = 0;
    std::wstring result;
    std::wstring error;
#if LINGBUILDER_CEF3_AVAILABLE
    CefRefPtr<CefRegistration> registration;
#else
    void* registration = nullptr;
#endif
};

